//! Fixed original static field/proc-reference errors over the unique evaluator.
use super::*;
use crate::{checker_expression_visit::StaticObserver,checker_static_reference::Failure,checker_original_expression_debug::{with_call_debug,CallDebug}};
struct Static<'archive,'body,'loan,'work,W>{archive:&'archive BodyArchive,body:&'loan ArchivedBody<'body>,work:&'work mut W,checkpoint:&'work dyn Fn()->io::Result<()>,rows:Vec<Row>}
impl<W:EffectReportWork> Static<'_,'_,'_,'_,W>{fn emit(&mut self,at:Span,expression:Span,message:String)->Result<(),PolicyFailure>{push(self.work,&mut self.rows,Row{diagnostic:Diagnostic{family:"static_reference",severity:Severity::Error,span:at,expression_span:expression,message,notes:Vec::new()},synthetic:false})}}
impl<W:EffectReportWork> StaticObserver<PolicyFailure> for Static<'_,'_,'_,'_,W>{fn failure(&mut self,failure:Failure<'_>,name:&str,procedure:bool,at:Span,expression:Span)->Result<(),PolicyFailure>{(self.checkpoint)().map_err(PolicyFailure::Operational)?;let label=if procedure{"static proc reference"}else{"static access"};let message=match failure{Failure::NoValue=>text(self.work,format_args!("no typepath found for: {name:?}"))?,Failure::MissingField(owner)|Failure::MissingProc(owner)=>{let owner=self.archive.tree().symbols().text(owner).ok_or("static error owner spelling absent")?;let owner=if owner=="/"{"(global)"}else{owner};let noun=if procedure{"proc"}else{"field"};text(self.work,format_args!("undefined {noun}: {name:?} on {owner}"))?},Failure::NonPath(value)|Failure::MissingType(value)=>{let missing=matches!(failure,Failure::MissingType(_));let body=self.body;let checkpoint=self.checkpoint;return with_call_debug(body,CallDebug::Display(value),checkpoint,|word|{let noun=if missing{"an existing typepath"}else{"a static typepath"};let message=text(self.work,format_args!("{label} requires {noun}, {word} found instead"))?;self.emit(at,expression,message)})}};self.emit(at,expression,message)}}
pub fn with_archived_body<W:EffectReportWork,R:Resolver+?Sized>(archive:&BodyArchive,body:&ArchivedBody<'_>,resolver:&R,profile:PackedU128,work:&mut W,checkpoint:&dyn Fn()->io::Result<()>,consume:impl FnOnce(&Findings<'_>)->Result<(),PolicyFailure>)->Result<(),PolicyFailure>{checkpoint().map_err(PolicyFailure::Operational)?;if !body.belongs_to(archive)||resolver.source_owner()!=Some(std::ptr::from_ref(archive.tree()).cast()){return Err("static reference body/resolver is foreign".into())}archive.tree().validate_checker_builtin_profile(profile).map_err(|e|format!("static reference actual profile: {e:?}"))?;let mut observer=Static{archive,body,work,checkpoint,rows:Vec::new()};let pending=(||{crate::checker_expression_visit::static_references_archived(archive,body,resolver,profile,checkpoint,&mut observer)?;let findings=Findings::from_rows(archive,std::mem::take(&mut observer.rows));checkpoint().map_err(PolicyFailure::Operational)?;consume(&findings)})();if matches!(&pending,Err(PolicyFailure::Operational(_))){return pending}checkpoint().map_err(PolicyFailure::Operational)?;pending}
